import React, { useState, useCallback } from "react";
import {
  getReaders,
  deleteReader,
  updateReader,
  addReader,
  getReadersBorrowings,
} from "../services/readerService";
import BorrowingsModal from "./borrowingsModal";
import { handleCancelBorrowing } from "../services/borrowingService";
import { MenuBook } from "@material-ui/icons/";
import useManagedList from "../hooks/useManagedList";

// readers' POST response is shaped { message: reader } rather than the
// created reader directly (unlike categories/places) — normalize it here so
// useManagedList can stay shape-agnostic.
const addReaderNormalized = async (name) => {
  const { data } = await addReader(name);
  return { data: data.message };
};

const ManageReaders = () => {
  const {
    items: readers,
    editingId,
    editedName,
    setEditedName,
    newName,
    setNewName,
    startEdit,
    handleAdd,
    handleEdit,
    handleDelete,
  } = useManagedList({
    getAll: getReaders,
    add: addReaderNormalized,
    update: updateReader,
    remove: deleteReader,
  });

  const [borrowings, setBorrowings] = useState(null);
  const [borrowingsReader, setBorrowingsReader] = useState(null);

  const handleOpenBorrowingDetails = useCallback(async (reader) => {
    const { data } = await getReadersBorrowings(reader.id);
    setBorrowingsReader(reader.name);
    setBorrowings(data);
  }, []);

  // Returns the request promise so the modal can show success/failure.
  const onCancelBorrowing = useCallback(async (toDelete) => {
    await handleCancelBorrowing(toDelete);
    setBorrowings((prev) => prev.filter((b) => b.id !== toDelete.id));
  }, []);

  return (
    <React.Fragment>
      <div className="admin-section">
        <div className="card admin-section__card">
          <div className="card-body">
            <h5 className="mb-1">Czytelniczki i czytelnicy</h5>
          <p className="text-muted small mb-3">Kliknij nazwę, żeby ją zmienić (Enter zapisuje). Nową osobę dodasz w ostatnim wierszu.</p>
            <table className="table table-hover">
              <tbody>
                {readers.map((reader) => (
                  <tr key={reader.id}>
                    {editingId === reader.id ? (
                      <td>
                        <input
                        className="form-control"
                        value={editedName}
                        onChange={(e) => setEditedName(e.target.value)}
                        onKeyDown={(e) => handleEdit(e, reader)}
                        noValidate
                      />
                      </td>
                    ) : (
                      <td onClick={() => startEdit(reader)}>{reader.name}</td>
                    )}

                    <td>
                      <button
                        className="btn btn-outline-danger btn-sm"
                        onClick={() => handleDelete(reader)}
                      >
                        X
                      </button>
                    </td>
                    <td>
                      <button
                        className="btn btn-outline-primary btn-sm"
                        onClick={() => handleOpenBorrowingDetails(reader)}
                      >
                        <MenuBook />
                      </button>
                    </td>
                  </tr>
                ))}
                <tr>
                  <td colSpan={3}>
                    <input
                    className="form-control"
                    value={newName}
                    onChange={(e) => setNewName(e.target.value)}
                    onKeyDown={handleAdd}
                    placeholder="Nowa czytelniczka..."
                    noValidate
                  />
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
        </div>
      </div>
      <BorrowingsModal
        borrowings={borrowings}
        onCancelBorrowing={onCancelBorrowing}
        title={borrowingsReader ? `Wypożyczenia — ${borrowingsReader}` : "Wypożyczenia"}
        onHide={() => setBorrowings(null)}
      />
    </React.Fragment>
  );
};

export default ManageReaders;
